package com.rpb.reservation.workforce.leave.account;
import static com.rpb.reservation.workforce.leave.account.LeaveAccountDtos.*;
import static com.rpb.reservation.workforce.compliance.ComplianceDtos.*;
import com.rpb.reservation.workforce.compliance.*;import com.rpb.reservation.workforce.domain.WorkforceException;
import com.rpb.reservation.walkin.api.CurrentActor;
import java.math.*;import java.time.*;import java.util.*;
import org.springframework.stereotype.Component;
/** Shared balance arithmetic and mutations. Caller holds employee + source-write locks in one transaction. */
@Component public class LeaveBalanceEngine {
 private final LeaveAccountRepository repo;private final ComplianceRepository policies;private final Clock clock;private final LeaveAccrualAbsences absences;
 public LeaveBalanceEngine(LeaveAccountRepository repo,ComplianceRepository policies,Clock clock){this(repo,policies,clock,null);}
 @org.springframework.beans.factory.annotation.Autowired public LeaveBalanceEngine(LeaveAccountRepository repo,ComplianceRepository policies,Clock clock,LeaveAccrualAbsences absences){this.repo=repo;this.policies=policies;this.clock=clock;this.absences=absences;}
 public LocalDate today(){return LocalDate.now(clock.withZone(ZoneId.of("Asia/Singapore")));}
 private LocalDate asOf(UUID tenant,Account a){var on=today().isAfter(LocalDate.of(a.year(),12,31))?LocalDate.of(a.year(),12,31):today();var left=repo.leftOn(tenant,a.employeeId()).orElse(null);return left!=null&&left.isBefore(on)?left:on;}
 public Contract contract(UUID tenant,Account a){return policies.contracts(tenant,a.employeeId()).stream().filter(c->c.id().equals(a.contractId())&&c.companyId().equals(a.companyId())).findFirst().orElseThrow(WorkforceException::missing);}
 public Policy policy(UUID tenant,Account a){var c=contract(tenant,a);return policies.policy(tenant,c.policyId(),c.policyVersion()).orElseThrow(WorkforceException::missing);}
 public BigDecimal entitlement(UUID tenant,Policy p,Contract c,String kind,LocalDate on){if(on.isBefore(c.serviceStart()))return BigDecimal.ZERO;if(kind.equals("annual"))return LeaveEntitlement.calendarAnnual(p.rules(),c.serviceStart(),on,c.weeklyHours(),c.comparableWeeklyHours(),c.comparableDailyHours(),absences==null?Map.of():absences.days(tenant,c.companyId(),c.employeeId(),c.serviceStart(),on)).earned();if(kind.equals("company"))return BigDecimal.ZERO;int months=Math.toIntExact(java.time.temporal.ChronoUnit.MONTHS.between(c.serviceStart(),on));var sick=LeaveEntitlement.sick(p.rules(),months,c.weeklyHours(),c.comparableWeeklyHours(),c.comparableDailyHours());return kind.equals("sick")?sick.outpatient():sick.hospitalTotal();}
 public LocalDate expiry(Policy p,int year,String kind){return kind.equals("annual")?LocalDate.of(year,12,31).plusMonths(p.rules().carryMonths()):LocalDate.of(year,12,31).plusMonths(kind.equals("company")?p.rules().companyCarryMonths():0);}
 public LocalDate expiry(Policy p,Contract c,int year,String kind){var calendar=expiry(p,year,kind);if(!kind.equals("annual"))return calendar;var serviceEnd=c.serviceStart().withYear(year).plusYears(1).minusDays(1);var statutory=serviceEnd.plusMonths(p.rules().carryMonths());return statutory.isAfter(calendar)?statutory:calendar;}
 public List<String> issues(UUID tenant,Account a){var issues=new ArrayList<String>();var c=contract(tenant,a);var on=asOf(tenant,a);if(on.isBefore(a.openingOn()))return List.of();var p=policy(tenant,a);if(on.isAfter(p.effectiveTo()))issues.add("COMPLIANCE_POLICY_EXPIRED");var latest=policies.contract(tenant,a.employeeId(),on).orElse(null);if(latest==null||!latest.id().equals(c.id()))issues.add("LEAVE_CONTRACT_REVIEW_REQUIRED");if(a.kind().equals("annual")&&entitlement(tenant,p,c,a.kind(),on).subtract(a.baselineAccrual()).subtract(repo.credited(tenant,a.id(),"accrual")).signum()<0)issues.add("LEAVE_ACCRUAL_REVIEW_REQUIRED");return List.copyOf(issues);}
 public BigDecimal due(UUID tenant,Account a){if(a.kind().equals("company")||!issues(tenant,a).isEmpty()||today().isBefore(a.openingOn()))return BigDecimal.ZERO;var on=asOf(tenant,a);if(on.isBefore(a.openingOn()))return BigDecimal.ZERO;return entitlement(tenant,policy(tenant,a),contract(tenant,a),a.kind(),on).subtract(a.baselineAccrual()).subtract(repo.credited(tenant,a.id(),"accrual")).max(BigDecimal.ZERO);}
 public Balance balance(UUID tenant,Account a){var lots=repo.lots(tenant,a.id());var history=repo.history(tenant,a.id());var available=BigDecimal.ZERO;var reserved=BigDecimal.ZERO;for(var l:lots){reserved=reserved.add(l.reserved());if(!l.expiresOn().isBefore(today()))available=available.add(l.remaining().subtract(l.reserved()));}var used=history.stream().filter(e->Set.of("use","cancel-use").contains(e.operation())).map(Entry::quantity).reduce(BigDecimal.ZERO,BigDecimal::add).negate();var encash=history.stream().filter(e->Set.of("encash","reverse-encash").contains(e.operation())).map(Entry::quantity).reduce(BigDecimal.ZERO,BigDecimal::add).negate();var due=due(tenant,a);var usable=available.add(due);if(a.kind().equals("sick")){var shared=repo.accounts(tenant,a.employeeId(),a.year()).stream().filter(x->x.companyId().equals(a.companyId())&&x.kind().equals("hospital")).findFirst().orElse(null);if(shared!=null)usable=usable.min(balance(tenant,shared).available());}return new Balance(a,usable,reserved,used,encash,due,lots,history,issues(tenant,a));}
 public void accrue(CurrentActor a,Account account){var due=due(a.tenantId(),account);if(due.signum()>0)repo.credit(a.tenantId(),account,"accrual","accrual:"+account.version()+":"+today(),expiry(policy(a.tenantId(),account),contract(a.tenantId(),account),account.year(),account.kind()),due);}
 public void reserve(CurrentActor a,Account account,UUID source,String sourceKind,LocalDate workDate,BigDecimal quantity){if(quantity==null||quantity.signum()<=0||quantity.scale()>6)throw WorkforceException.invalid();var issues=issues(a.tenantId(),account);if(!issues.isEmpty())throw new WorkforceException(issues.getFirst(),409);accrue(a,account);var remaining=quantity;for(var lot:repo.lots(a.tenantId(),account.id())){if(lot.expiresOn().isBefore(workDate))continue;var usable=lot.remaining().subtract(lot.reserved()).max(BigDecimal.ZERO);var take=usable.min(remaining);if(take.signum()>0){repo.hold(a.tenantId(),source,sourceKind,account.id(),lot.id(),take);remaining=remaining.subtract(take);}if(remaining.signum()==0)break;}if(remaining.signum()!=0)throw new WorkforceException("LEAVE_BALANCE_INSUFFICIENT",409);}
 public void transition(CurrentActor a,UUID source,String target,String reason){var holds=repo.holds(a.tenantId(),source);for(var h:holds){var account=repo.find(a.tenantId(),h.accountId()).orElseThrow();if(target.equals("used")&&h.status().equals("reserved"))repo.entry(a.tenantId(),a.actorId(),account,h.lotId(),source.toString(),h.sourceKind().equals("encashment")?"encash":"use",h.quantity().negate(),reason);else if(target.equals("released")&&h.status().equals("used"))repo.entry(a.tenantId(),a.actorId(),account,h.lotId(),source.toString(),h.sourceKind().equals("encashment")?"reverse-encash":"cancel-use",h.quantity(),reason);else if(target.equals("reserved")||target.equals("used")&&!h.status().equals("used"))throw WorkforceException.conflict();if(!h.status().equals(target)&&h.status().equals("reserved")&&target.equals("released"))repo.touch(a.tenantId(),account.id());}repo.holdStatus(a.tenantId(),source,target);}
}
